function fewestFlips(s: string): number {
  let a = "", b = "";
  for (let i = 0; i < s.length; i++) {
    a += i % 2 === 0 ? "0" : "1";
    b += i % 2 === 0 ? "1" : "0";
  }
  let da = 0, db = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== a[i]) da++;
    if (s[i] !== b[i]) db++;
  }
  return Math.min(da, db);
}

