class Solution:
    def fewestFlips(self, s: str) -> int:
        n = len(s)
        a = "".join("0" if i % 2 == 0 else "1" for i in range(n))
        b = "".join("1" if i % 2 == 0 else "0" for i in range(n))
        da = sum(x != y for x, y in zip(s, a))
        db = sum(x != y for x, y in zip(s, b))
        return min(da, db)

