function fewestFlips(s: string): number {
  let c = 0;
  for (let i = 0; i < s.length; i++) {
    // target bit at i is i % 2 for the string "0101..."
    if (s.charCodeAt(i) - 48 !== i % 2) c++;
  }
  return Math.min(c, s.length - c);
}

